(13, 'Zero Defect Zero Effect (ZED) Certification - What\'s Your Score?', 'Lorem ipsum dolor sit amet, consectetur adipisicing elit, sed do eiusmod\r\ntempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam,\r\n', 'https://youtu.be/KDlRsYNZIQk', 'Zero Defect Zero Effect (ZED) Certification - What\'s Your Score?', 1, 2, '2022-04-29 01:06:08', 1, '2022-04-29 06:35:35', 1),
(14, 'NIDHI Video', 'Lorem ipsum dolor sit amet, consectetur adipisicing elit, sed do eiusmod\r\ntempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam,\r\n', 'http://zedv2.umon.in/uploads/NIDHI_video_final.mp4', '', 2, 2, '2022-04-29 01:04:45', 1, '2021-10-20 05:33:54', 1),
(15, 'NIDHI Video 2', 'http://zedv2.umon.in/uploads/NIDHI_video_final.mp4', 'http://zedv2.umon.in/uploads/NIDHI_video_final.mp4', 'MSME Sustainable (ZED) Certification is an extensive drive to create awareness amongst MSMEs about Zero Defect Zero Effect (ZED) practices and motivate and incentivise them for ZED Certification while also encouraging them to become MSME Champions.', 3, 2, '2022-04-29 01:04:45', 1, '2021-10-20 05:33:48', 1),
(16, 'NIDHI Video 3', 'MSME Sustainable (ZED) Certification is an extensive drive to create awareness amongst MSMEs about Zero Defect Zero Effect (ZED) practices and motivate and incentivise them for ZED Certification while also encouraging them to become MSME Champions.', 'http://zedv2.umon.in/uploads/NIDHI_video_final.mp4', 'MSME Sustainable (ZED) Certification is an extensive drive to create awareness amongst MSMEs about Zero Defect Zero Effect (ZED) practices and motivate and incentivise them for ZED Certification while also encouraging them to become MSME Champions.', 4, 2, '2022-04-29 01:04:45', 1, '2021-10-20 05:33:43', 1),
(17, 'NIDHI Video 4', 'MSME Sustainable (ZED) Certification is an extensive drive to create awareness amongst MSMEs about Zero Defect Zero Effect (ZED) practices and motivate and incentivise them for ZED Certification while also encouraging them to become MSME Champions.', 'http://zedv2.umon.in/uploads/NIDHI_video_final.mp4', 'MSME Sustainable (ZED) Certification is an extensive drive to create awareness amongst MSMEs about Zero Defect Zero Effect (ZED) practices and motivate and incentivise them for ZED Certification while also encouraging them to become MSME Champions.', 5, 2, '2022-04-29 01:04:45', 1, '2021-10-20 05:33:39', 1),
(18, 'NIDHI Video 5', 'MSME Sustainable (ZED) Certification is an extensive drive to create awareness amongst MSMEs about Zero Defect Zero Effect (ZED) practices and motivate and incentivise them for ZED Certification while also encouraging them to become MSME Champions.', 'http://zedv2.umon.in/uploads/NIDHI_video_final.mp4', 'MSME Sustainable (ZED) Certification is an extensive drive to create awareness amongst MSMEs about Zero Defect Zero Effect (ZED) practices and motivate and incentivise them for ZED Certification while also encouraging them to become MSME Champions.', 6, 2, '2022-04-29 01:04:45', 1, '2021-10-20 05:33:34', 1),
(19, 'NIDHI Video 6', 'MSME Sustainable (ZED) Certification is an extensive drive to create awareness amongst MSMEs about Zero Defect Zero Effect (ZED) practices and motivate and incentivise them for ZED Certification while also encouraging them to become MSME Champions.', 'https://www.youtube.com/embed/hm0pkySSdP0', 'MSME Sustainable (ZED) Certification is an extensive drive to create awareness amongst MSMEs about Zero Defect Zero Effect (ZED) practices and motivate and incentivise them for ZED Certification while also encouraging them to become MSME Champions.', 7, 2, '2022-04-29 01:04:45', 1, '2021-10-20 05:33:28', 1),
(20, 'Launch of MSME Sustainable (ZED) Scheme', '', 'https://youtu.be/Iq0-RwtGGJs', '', 1, 2, '2022-04-29 01:06:08', 1, '2022-04-29 01:02:46', 0),
(21, 'Launch of MSME Sustainable (ZED) Certification Scheme', 'Union Minister for Micro, Small and Medium Enterprises Shri Narayan Rane  launched the MSME Sustainable (ZED) Certification Scheme on April 28, 2022, 11:00 AM.', 'https://www.youtube.com/embed/Iq0-RwtGGJs', 'Launch of MSME Sustainable (ZED) Certification Scheme', 10, 1, '2023-01-08 12:19:38', 1, '2023-01-08 05:49:38', 1),
