(32, 'F4', 'Systems for Natural Resource Conservation', 'Design or select processes that eliminate or reduce natural resource use and substitute conventional energy sources with renewable sources', '7', 13, '', '', '', '', '', '', '', 2, '2017-05-30 06:17:33', 1, '2017-05-08 03:23:57', 0),
(33, 'G1', 'Installation of Environmental Protection and Measuring Systems', 'Install Plant & equipment, monitoring mechanisms required to eliminate, reduce, treat or dispose effluents/emissions and solid wastes as per design for every new process or product line\r\n', '7', 14, '', 'greenwhite', '', '', '', '', '', 2, '2017-05-30 06:17:33', 1, '2017-05-23 02:38:30', 0),
(34, 'H1', 'Planned Maintenance of Environmental Management Systems', 'Ensure the maintenance of equipment installed for environmental control to keep them operational with lowest downtime.\r\n', '7', 15, '', 'greenwhite', '', '', '', '', '', 2, '2017-05-30 06:17:33', 1, '2017-05-23 02:39:40', 0),
(35, 'H2', 'Planned Maintenance of Energy Control Systems', 'Ensure the maintenance of all equipment installed to keep the energy consumption level at the optimum, prevent energy wastage and leakages.\r\n', '7', 15, 'redorange', 'greenwhite', '', '', '', '', '', 2, '2017-05-30 06:17:33', 1, '2017-05-23 02:39:59', 0),
(36, 'I1', 'Design Compliance with Regulatory Requirements', 'Develop and design the product to fulfill compliance with environmental regulatory requirements for products.\r\n', '7', 16, 'redorange', 'greenwhite', '', '', '', '', '', 2, '2017-05-30 06:17:33', 1, '2017-05-23 02:40:58', 0),
(37, 'J1', 'Disposal After Use', 'Have information to educate consumer for product disposal in an environmentally safe manner and to provide for disposal systems where required by statute or environment impact level is high\r\n', '7', 17, 'redorange', 'greenwhite', '', '', '', '', '', 2, '2017-05-30 06:17:33', 1, '2017-05-23 02:41:25', 0),
