INSERT INTO `zed_parameter` (`parameterid`, `code`, `name`, `description`, `sectorid`, `disciplineid`, `ro`, `gw`, `level1_comment`, `level2_comment`, `level3_comment`, `level4_comment`, `level5_comment`, `status`, `created_on`, `created_by`, `modified_on`, `modified_by`) VALUES
(119, 'A3', 'Low Cost Automation', 'Replacing manual efforts with alternate mechanised operations developed locally to reduce quality variations, time & cost of operations', '7', 8, '', '', 'No emphasis or awareness on low cost automation\r\nLow cost automation is not done\r\nImprovement goals for low cost automation are not measured\r\n', 'Low cost automation mainly done to improve productivity by senior management\r\nLow cost automation is done on adhoc basis\r\nImprovement goals met in case of &lt;50%\r\n', 'Low cost automation aimed to improve productivity, quality and capacity utilization and goals are set\r\nLow cost automation done in small groups using various tools (e.g. Kaizen sheets, one point lessons)\r\nImprovement goals met in case of 50%-75%\r\n', 'Low cost automation aimed to address energy conservation along with productivity, quality and capacity utilisation\r\nLow cost automation is evident by usage of Pneumatic, hydraulic , electric , hybrid , electronic controlled systems in a wide variety of manufacturing areas\r\nImprovement goals met in case of >75% to 95%\r\n', ' Continuous identification of improvement areas to apply low cost automation system in place along with ensuring energy conservation\r\nLow cost automation has led to reduced man effort on machines by more than 50% especially on loading , feeding , setting , material handling , quality inspection & packaging\r\nImprovement goals met in case of >95% of cases\r\n', 1, '2017-05-30 10:15:10', 1, '2017-05-30 16:45:10', 0),
