INSERT INTO `zed_parameter` (`parameterid`, `code`, `name`, `description`, `sectorid`, `disciplineid`, `ro`, `gw`, `level1_comment`, `level2_comment`, `level3_comment`, `level4_comment`, `level5_comment`, `status`, `created_on`, `created_by`, `modified_on`, `modified_by`) VALUES
(1284, 'D4', 'Data Integrity', 'Maintenance of and assurance of accuracy and consistency of data over its entire life-cycle\r\n', '8', 11, '', '', 'No process/SOP to ensure data integrity in Quality control lab\r\nNo implementation plan to address data integrity issues\r\nNo review mechanism exists to review data integrity\r\n', 'SOP in place which ensures recording of all sampling and analysis data; Recording manual\r\nBasic Implementation challenges are resolved e.g. admin password available, raw data deletable, audit trail disabled\r\nData integrity reviewed on adhoc basis by IT team\r\n', 'SOP in line with 21 CFR guidelines; Lab equipment are 21 CFR compliant or in the process of being made 21 CFR compliant.\r\n Critical implementation challenges are addressed e.g. Historical chromatograms reviewed to ensure data integrity\r\nFrequent data integrity reviews done by the Quality team, no escalation to management\r\n', ' All lab testing equipment are 21 CFR compliant.\r\n Implementation challenges are resolved. Clear protocols in place for analysis and experimentation of other equipments on site (beyond QC lab e.g. PD lab)\r\nFrequent data integrity reviews done by the Quality team, method implemented for escalation to management\r\n', ' All lab equipment including testing equipment are 21 CFR compliant.\r\n Lab softwares related to 21 CFR compliance fully integrated and system validated to ensure no issues in implementation\r\nFrequent data integrity reviews done by the Quality team and no data integrity issues found in last 1 year\r\n', 1, '2017-05-31 10:17:06', 1, '2017-05-31 04:47:06', 0),
(1285, 'D4', 'Data Integrity', 'Maintenance of and assurance of accuracy and consistency of data over its entire life-cycle\r\n', '9', 11, '', '', 'No process/SOP to ensure data integrity in Quality control lab\r\nNo implementation plan to address data integrity issues\r\nNo review mechanism exists to review data integrity\r\n', 'SOP in place which ensures recording of all sampling and analysis data; Recording manual\r\nBasic Implementation challenges are resolved e.g. admin password available, raw data deletable, audit trail disabled\r\nData integrity reviewed on adhoc basis by IT team\r\n', 'SOP in line with 21 CFR guidelines; Lab equipment are 21 CFR compliant or in the process of being made 21 CFR compliant.\r\n Critical implementation challenges are addressed e.g. Historical chromatograms reviewed to ensure data integrity\r\nFrequent data integrity reviews done by the Quality team, no escalation to management\r\n', ' All lab testing equipment are 21 CFR compliant.\r\n Implementation challenges are resolved. Clear protocols in place for analysis and experimentation of other equipments on site (beyond QC lab e.g. PD lab)\r\nFrequent data integrity reviews done by the Quality team, method implemented for escalation to management\r\n', ' All lab equipment including testing equipment are 21 CFR compliant.\r\n Lab softwares related to 21 CFR compliance fully integrated and system validated to ensure no issues in implementation\r\nFrequent data integrity reviews done by the Quality team and no data integrity issues found in last 1 year\r\n', 1, '2017-05-31 10:17:06', 1, '2017-05-31 04:47:06', 0),
(1286, 'I2', 'Design Capability for Environment', 'Design capability as per environment aspect\r\n', '10', 16, '', '', 'Organization has no design function, changes are made as and when required\r\nNo process exists for making design improvements ; Use traditional methods like point papers for weaving, etc.\r\nNo monitoring/assessment of design capability\r\n', 'Organization has design and development groups to design product as per customer needs\r\nDesign capability is improved by design modification as necessitated by customer complaints or internal failures; - Developing design capability and building understanding of properties of yarn, fabric and dyes, techniques of sizing, etc.\r\nMonitoring/assessment of design capability is in place but not followed\r\n', 'Design group in place with design review a common practice\r\nLife Testing -Normal and accelerated performed on samples for design improvements but results not evaluated .IT enabled design tools and implementation of design processes like QFD\r\nDesign capability is assessed on a reactive basis e.g an index of customer complaints and extent of failures found during manufacturing\r\n', 'Design group in place with proactive Design capability. All possible reasons for low capability are investigated\r\nAll possible reasons for low capability are investigated using several tools/techniques- e.g.. seven tools, FMEA and DOE\r\nDesign capability is proactively assessed e.g.. based on variation in product performance and analysis between actual and target performance; - Capability levels are monitored to maintain high levels\r\n', 'Proactive design planning by design group \r\nCapability is improved by analysing and improving characteristics on each aspect in low capability areas.\r\nProduct design capability is assessed in sigma level through a comprehensive score card incorporating several elements including parts, processes and performance\r\n', 1, '2017-05-31 10:54:10', 1, '2017-05-31 05:24:10', 0),
(1287, 'I2', 'Design Capability for Environment', 'Design capability as per environment aspect\r\n', '12', 16, '', '', 'Organization has no design function, changes are made as and when required\r\nNo process exists for making design improvements ; Use traditional methods like point papers for weaving, etc.\r\nNo monitoring/assessment of design capability\r\n', 'Organization has design and development groups to design product as per customer needs\r\nDesign capability is improved by design modification as necessitated by customer complaints or internal failures; - Developing design capability and building understanding of properties of yarn, fabric and dyes, techniques of sizing, etc.\r\nMonitoring/assessment of design capability is in place but not followed\r\n', 'Design group in place with design review a common practice\r\nLife Testing -Normal and accelerated performed on samples for design improvements but results not evaluated .IT enabled design tools and implementation of design processes like QFD\r\nDesign capability is assessed on a reactive basis e.g an index of customer complaints and extent of failures found during manufacturing\r\n', 'Design group in place with proactive Design capability. All possible reasons for low capability are investigated\r\nAll possible reasons for low capability are investigated using several tools/techniques- e.g.. seven tools, FMEA and DOE\r\nDesign capability is proactively assessed e.g.. based on variation in product performance and analysis between actual and target performance; - Capability levels are monitored to maintain high levels\r\n', 'Proactive design planning by design group \r\nCapability is improved by analysing and improving characteristics on each aspect in low capability areas.\r\nProduct design capability is assessed in sigma level through a comprehensive score card incorporating several elements including parts, processes and performance\r\n', 1, '2017-05-31 10:54:10', 1, '2017-05-31 05:24:10', 0),
(1288, 'O4', 'Cost of Poor Quality', 'Cost of poor quality (rework, rejects, return) in percentage of industry benchmark\r\n', '10', 22, '', '', 'In-process manufacturing quality not measured\r\n', 'In-process manufacturing quality is &lt; 50% of industry benchmark\r\n', 'In-process manufacturing quality is 50-75% of industry benchmark\r\n', 'In-process manufacturing quality is >75-95% of industry benchmark\r\n', 'In-process manufacturing quality is >95% of industry benchmark\r\n', 1, '2017-05-31 11:39:35', 1, '2017-05-31 06:09:35', 0),
